svg.script:

(function() {
  var root = document.getElementById('a12p2-svg-root');
  if (!root || root.getAttribute('data-a12p2-bound') === 'true') return;
  root.setAttribute('data-a12p2-bound', 'true');

  var btnStep1 = document.getElementById('a12p2-btn-step1');
  var btnStep2 = document.getElementById('a12p2-btn-step2');
  var btnStep3 = document.getElementById('a12p2-btn-step3');
  var btnStepAll = document.getElementById('a12p2-btn-stepall');

  var buttons = [
    { el: btnStep1, step: '1' },
    { el: btnStep2, step: '2' },
    { el: btnStep3, step: '3' },
    { el: btnStepAll, step: 'all' }
  ];

  function setStep(targetStep) {
    root.setAttribute('data-step', targetStep);
    buttons.forEach(function(item) {
      if (!item.el) return;
      var isActive = (item.step === targetStep);
      item.el.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
  }

  buttons.forEach(function(item) {
    if (!item.el) return;
    item.el.addEventListener('click', function() {
      setStep(item.step);
    });
    item.el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        setStep(item.step);
      }
    });
  });
})();
